def reverse_string(s):
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a string, got %s" % type(s).__name__)
    chars = []
    for index in range(len(s) - 1, -1, -1):
        chars.append(s[index])
    return "".join(chars)


def is_palindrome(s, ignore_case=True):
    cleaned = "".join(ch for ch in s if ch.isalnum())
    if ignore_case:
        cleaned = cleaned.lower()
    return cleaned == reverse_string(cleaned)


def reverse_words(sentence):
    reversed_words = []
    for word in sentence.split():
        reversed_words.append(reverse_string(word))
    return " ".join(reversed_words)


def reverse_lines(text):
    output = []
    for line in text.splitlines():
        output.append(reverse_string(line.rstrip()))
    return "\n".join(output)


def format_report(samples):
    width = 0
    for sample in samples:
        if len(sample) > width:
            width = len(sample)
    rows = []
    for sample in samples:
        flipped = reverse_string(sample)
        if is_palindrome(sample):
            note = "palindrome"
        else:
            note = "-"
        rows.append("%-*s -> %-*s  %s" % (width, sample, width, flipped, note))
    return rows


def main():
    samples = ["hello", "Python", "Racecar", "A man, a plan, a canal: Panama"]
    for row in format_report(samples):
        print(row)

    sentence = "reverse each word in place"
    print()
    print(sentence)
    print(reverse_words(sentence))

    text = "first line\nsecond line   \nthird line"
    print()
    print(reverse_lines(text))


if __name__ == "__main__":
    main()

