def fibonacci_sequence(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    else:
        sequence = [0, 1]
        while len(sequence) < n:
            next_fib = sequence[-1] + sequence[-2]
            sequence.append(next_fib)
        return sequence

if __name__ == '__main__':
    print(f"Fibonacci sequence for n=0: {fibonacci_sequence(0)}")
    print(f"Fibonacci sequence for n=1: {fibonacci_sequence(1)}")
    print(f"Fibonacci sequence for n=2: {fibonacci_sequence(2)}")
    print(f"Fibonacci sequence for n=5: {fibonacci_sequence(5)}")
    print(f"Fibonacci sequence for n=10: {fibonacci_sequence(10)}")

    # Another test case
    test_n = 7
    expected_output = [0, 1, 1, 2, 3, 5, 8]
    actual_output = fibonacci_sequence(test_n)
    print(f"Fibonacci sequence for n={test_n}: {actual_output}")
    if actual_output == expected_output:
        print("Test passed for n=7.")
    else:
        print("Test failed for n=7.")

