		keys = sorted(groups[name], key=repr)
		if keys:
			details = []
			for key in keys:
				if name == "overridden":
					details.append("%r: %r -> %r" % (key, dict1[key], merged_dict[key]))
				else:
					details.append("%r: %r" % (key, merged_dict[key]))
			lines.append("  %-10s %s" % (name + ":", ", ".join(details)))
		else:
			lines.append("  %-10s (none)" % (name + ":"))
	return "\n".join(lines)


