def least_frequent_char(text):
    if not text:
        return ''

    char_counts = {}
    for char in text:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    min_count = float('inf')
    least_freq_char = ''

    for char in text:
        current_count = char_counts[char]
        if current_count < min_count:
            min_count = current_count
            least_freq_char = char

    return least_freq_char

