def run_length_decode(encoded_string):
    decoded_parts = []
    i = 0
    n = len(encoded_string)
    while i < n:
        count_str = ""
        while i < n and encoded_string[i].isdigit():
            count_str += encoded_string[i]
            i += 1

        if count_str:
            count = int(count_str)
            if i < n:
                char = encoded_string[i]
                decoded_parts.append(char * count)
                i += 1
            else:
                # Handle cases where count is at the end without a character, though not expected by problem description
                pass 
        else:
            # Handle cases where a character might appear without a count,
            # treating it as a count of 1. Not explicitly in problem desc, but good for robustness.
            if i < n:
                char = encoded_string[i]
                decoded_parts.append(char)
                i += 1

    return "".join(decoded_parts)

