def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            # This case should not be reached based on the problem description
            # which states "only parentheses '()', square brackets '[]', and curly braces '{}'"
            pass

    return not stack

