def are_anagrams(str1, str2):
    def normalize_string(s):
        normalized = ""
        for char in s:
            if char.isalpha():
                normalized += char.lower()
        return normalized

    normalized_str1 = normalize_string(str1)
    normalized_str2 = normalize_string(str2)

    if len(normalized_str1) != len(normalized_str2):
        return False

    char_count1 = {}
    for char in normalized_str1:
        char_count1[char] = char_count1.get(char, 0) + 1

    char_count2 = {}
    for char in normalized_str2:
        char_count2[char] = char_count2.get(char, 0) + 1

    for char, count in char_count1.items():
        if char_count2.get(char) != count:
            return False

    return True

