def parse_url_params(query_string):
    """Parse a URL query string into a dictionary of key-value pairs."""
    if not isinstance(query_string, str):
        raise TypeError('query_string must be a str')
    params = {}
    for chunk in query_string.split('&'):
        if not chunk:
            continue
        if '=' in chunk:
            key, value = chunk.split('=', 1)
        else:
            key, value = chunk, ''
        key = key.strip()
        if key:
            params[key] = value.strip()
    return params


def extract_query(url):
    """Return the query part of a full URL (empty string when absent)."""
    without_fragment = url.split('#', 1)[0]
    if '?' in without_fragment:
        return without_fragment.split('?', 1)[1]
    return ''


def parse_url(url):
    """Parse the query section of a complete URL into a dictionary."""
    return parse_url_params(extract_query(url))


def format_params(params):
    """Build aligned 'key = value' report lines for a parsed query."""
    if not params:
        return ['(no parameters)']
    width = max(len(key) for key in params)
    lines = []
    for key, value in params.items():
        if value:
            lines.append('{0:<{1}} = {2}'.format(key, width, value))
        else:
            lines.append('{0:<{1}} = <empty>'.format(key, width))
    return lines


def main():
    queries = [
        'name=John&age=30',
        'q=python+programming',
        'a=1&&b=&c',
    ]
    urls = [
        'https://example.com/search?q=cats&page=2#results',
        'https://example.com/about',
    ]
    for query in queries:
        print('query:', query)
        for line in format_params(parse_url_params(query)):
            print('   ', line)
    for url in urls:
        print('url:', url)
        for line in format_params(parse_url(url)):
            print('   ', line)


if __name__ == '__main__':
    main()

