import sys

FEET_PER_METER = 3.28084
METER_ALIASES = ("m", "meter", "meters", "metre", "metres")
FOOT_ALIASES = ("ft", "foot", "feet")
UNIT_NAMES = {"m": "meters", "ft": "feet"}


def normalize_unit(unit):
    if not isinstance(unit, str):
        raise TypeError("unit must be a string, got %r" % (unit,))
    key = unit.strip().lower()
    if key in METER_ALIASES:
        return "m"
    if key in FOOT_ALIASES:
        return "ft"
    raise ValueError("unknown length unit: %r" % (unit,))


def convert_length(value, from_unit, to_unit):
    try:
        amount = float(value)
    except (TypeError, ValueError):
        raise ValueError("value must be a number, got %r" % (value,))
    source = normalize_unit(from_unit)
    target = normalize_unit(to_unit)
    if source == target:
        result = amount
    elif source == "m":
        result = amount * FEET_PER_METER
    else:
        result = amount / FEET_PER_METER
    return round(result, 10)


def parse_request(text):
    parts = text.replace(",", " ").split()
    if len(parts) != 3:
        raise ValueError("expected 'VALUE FROM_UNIT TO_UNIT', got %r" % (text,))
    number, source, target = parts
    return float(number), normalize_unit(source), normalize_unit(target)


def format_result(value, from_unit, to_unit):
    result = convert_length(value, from_unit, to_unit)
    source_name = UNIT_NAMES[normalize_unit(from_unit)]
    target_name = UNIT_NAMES[normalize_unit(to_unit)]
    return "%g %s = %g %s" % (value, source_name, result, target_name)


def run(lines):
    report = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            value, source, target = parse_request(stripped)
        except ValueError as error:
            report.append("error: %s" % error)
        else:
            report.append(format_result(value, source, target))
    return report


def main(argv):
    if len(argv) > 1:
        lines = [" ".join(argv[1:])]
    else:
        lines = sys.stdin
    for line in run(lines):
        print(line)


if __name__ == "__main__":
    main(sys.argv)

