def calculate_power(base, exponent):
    if not isinstance(base, (int, float)):
        raise TypeError("Base must be an integer or a float.")
    if not isinstance(exponent, int):
        raise TypeError("Exponent must be an integer.")

    if exponent == 0:
        return 1
    elif exponent < 0:
        # Handle negative exponents by calculating the reciprocal of the positive power
        positive_power = 1
        for _ in range(abs(exponent)):
            positive_power *= base
        return 1 / positive_power
    else:
        # Calculate positive exponents
        result = 1
        for _ in range(exponent):
            result *= base
        return result

# Example usage and testing:
if __name__ == "__main__":
    print(f"2 to the power of 3 is: {calculate_power(2, 3)}")
    print(f"5 to the power of 0 is: {calculate_power(5, 0)}")
