def integer_sqrt(n):
    """Return the largest integer r such that r * r <= n, using Newton's method."""
    if n < 2:
        return n
    guess = 1 << ((n.bit_length() + 1) // 2)
    while True:
        better = (guess + n // guess) // 2
        if better >= guess:
            return guess
        guess = better


def is_perfect_square(n):
    """Return True if the non-negative integer n is a perfect square."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n & 0xF not in (0, 1, 4, 9):
        return False
    root = integer_sqrt(n)
    return root * root == n


def parse_numbers(text):
    """Split text on whitespace and commas, returning the integers it contains."""
    numbers = []
    for token in text.replace(",", " ").split():
        if not token.isdigit():
            raise ValueError("not a non-negative integer: %r" % token)
        numbers.append(int(token))
    return numbers


def squares_up_to(limit):
    """Return every perfect square in the inclusive range 0..limit."""
    results = []
    root = 0
    while root * root <= limit:
        results.append(root * root)
        root += 1
    return results


def format_report(numbers):
    """Build a human readable line per number describing whether it is a square."""
    lines = []
    width = max((len(str(value)) for value in numbers), default=1)
    for value in numbers:
        if is_perfect_square(value):
            verdict = "is the square of %d" % integer_sqrt(value)
        else:
            verdict = "is not a perfect square"
        lines.append("%*d %s" % (width, value, verdict))
    return "\n".join(lines)


def main():
    sample = "0, 1, 2, 9, 10, 16, 25, 26, 144, 10000000000, 10000000001"
    numbers = parse_numbers(sample)
    print(format_report(numbers))
    limit = 50
    found = squares_up_to(limit)
    print("squares up to %d: %s" % (limit, " ".join(str(s) for s in found)))
    for bad in ("-4", "twelve"):
        try:
            parse_numbers(bad)
        except ValueError as exc:
            print("rejected input: %s" % exc)


if __name__ == "__main__":
