def calculate_percentage(part, whole):
    try:
        if not isinstance(part, (int, float)) or not isinstance(whole, (int, float)):
            raise TypeError("Both 'part' and 'whole' must be numbers.")

        if whole == 0:
            print("Warning: Division by zero attempted. Returning 0.0.")
            return 0.0
        else:
            percentage = (part / whole) * 100
            if percentage < 0:
                print("Warning: Negative percentage calculated.")
            return float(percentage)

    except TypeError as e:
        print(f"Error: {e}")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

