def simple_calculator(expression):
    for op in ['+', '-']:
        if op in expression:
            parts = expression.split(op)
            try:
                num1 = int(parts[0])
                num2 = int(parts[1])
            except ValueError:
                return "Error: Invalid number in expression."
            if op == '+':
                result = num1 + num2
            elif op == '-':
                result = num1 - num2
            else:
                return "Error: Unknown operator."
            return result

    try:
        return int(expression)
    except ValueError:
        return "Error: Invalid expression format."

