def list_to_dict(key_value_list):
    result_dict = {}
    if key_value_list:
        for item_pair in key_value_list:
            if isinstance(item_pair, list) and len(item_pair) == 2:
                key = item_pair[0]
                value = item_pair[1]
                try:
                    hash(key)
                    result_dict[key] = value
                except TypeError:
                    print(f"Skipping unhashable key: {key}")
            else:
                print(f"Skipping malformed item: {item_pair}")
    else:
        pass # Empty list, return empty dict
    return result_dict

