from datetime import date


def validate_birth_date(birth_year, birth_month, birth_day):
    """Return a date object, raising ValueError for impossible input."""
    try:
        birth = date(birth_year, birth_month, birth_day)
    except ValueError as exc:
        raise ValueError("invalid birth date: %s" % exc)
    if birth > date.today():
        raise ValueError("birth date lies in the future")
    return birth


def age_in_years(birth, today=None):
    """Full years elapsed between birth and today."""
    if today is None:
        today = date.today()
    years = today.year - birth.year
    if (today.month, today.day) < (birth.month, birth.day):
        years -= 1
    return years


def is_adult(birth_year, birth_month, birth_day, min_age):
    """True if the person born on the given date is at least min_age today."""
    if min_age < 0:
        raise ValueError("min_age must not be negative")
    birth = validate_birth_date(birth_year, birth_month, birth_day)
    return age_in_years(birth) >= min_age


def date_of_eligibility(birth, min_age):
    """The first day on which the person reaches min_age years."""
    target_year = birth.year + min_age
    if birth.month == 2 and birth.day == 29:
        leap = target_year % 4 == 0 and (target_year % 100 != 0 or target_year % 400 == 0)
        if not leap:
            return date(target_year, 3, 1)
    return date(target_year, birth.month, birth.day)


def describe(birth_year, birth_month, birth_day, min_age):
    """Human readable verdict for one person."""
    try:
        birth = validate_birth_date(birth_year, birth_month, birth_day)
    except ValueError as exc:
        return "%04d-%02d-%02d: %s" % (birth_year, birth_month, birth_day, exc)
    age = age_in_years(birth)
    if is_adult(birth_year, birth_month, birth_day, min_age):
        verdict = "is at least %d (age %d)" % (min_age, age)
    else:
        eligible = date_of_eligibility(birth, min_age)
        days_left = (eligible - date.today()).days
        verdict = "is only %d, eligible on %s (in %d days)" % (age, eligible, days_left)
    return "%s: %s" % (birth.isoformat(), verdict)


def main():
    people = [
        (2000, 1, 1, 18),
        (2010, 1, 1, 18),
        (2004, 2, 29, 21),
        (1990, 12, 31, 65),
        (2001, 13, 1, 18),
    ]
    today = date.today()
    print("Report for %s" % today.isoformat())
    adults = 0
    for year, month, day, min_age in people:
        print(describe(year, month, day, min_age))
        try:
            if is_adult(year, month, day, min_age):
                adults += 1
        except ValueError:
            continue
    print("%d of %d entries meet their age requirement" % (adults, len(people)))


if __name__ == "__main__":
    main()

