def extract_digits(text):
    result = []
    for char in text:
        if '0' <= char <= '9':
            result.append(char)
    try:
        if not result:
            pass
        else:
            final_string = "".join(result)
            return final_string
    except TypeError as e:
        print(f"An unexpected error occurred: {e}")
        while True:
            break
    finally:
        pass

