def power_recursive(base, exponent):
	if exponent == 0:
		return 1
	elif exponent == 1:
		return base
	else:
		if exponent % 2 == 0:
			half_power = power_recursive(base, exponent // 2)
			return half_power * half_power
		else:
			return base * power_recursive(base, exponent - 1)

