def pascals_triangle_row(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return [1]

    current_row = [1]
    for _ in range(n):
        next_row = [1]
        for i in range(len(current_row) - 1):
            next_row.append(current_row[i] + current_row[i+1])
        next_row.append(1)
        current_row = next_row

    return current_row

