def reverse_string_recursive(s):
    """Return the reverse of s, computed recursively."""
    if not isinstance(s, str):
        raise TypeError("reverse_string_recursive expects a string, got %r" % type(s).__name__)
    if len(s) <= 1:
        return s
    return reverse_string_recursive(s[1:]) + s[0]


def is_palindrome(s):
    """Report whether s reads the same forwards and backwards."""
    return s == reverse_string_recursive(s)


def normalize(s):
    """Keep only alphanumeric characters, lowercased, for palindrome testing."""
    kept = []
    for ch in s:
        if ch.isalnum():
            kept.append(ch.lower())
    return "".join(kept)


def reverse_words(sentence):
    """Reverse the order of whitespace-separated words in a sentence."""
    words = sentence.split()
    reversed_words = []
    while words:
        reversed_words.append(words.pop())
    return " ".join(reversed_words)


def describe(s):
    """Build a one-line description of how s behaves under reversal."""
    reversed_text = reverse_string_recursive(s)
    parts = ["%-14r -> %-14r" % (s, reversed_text)]
    cleaned = normalize(s)
    if cleaned and is_palindrome(cleaned):
        parts.append("palindrome")
    else:
        parts.append("not a palindrome")
    return " | ".join(parts)


def main():
    samples = [
        "hello",
        "",
        "a",
        "Racecar",
        "A man, a plan, a canal: Panama",
        "step on no pets",
    ]
    for sample in samples:
        print(describe(sample))

    sentence = "recursion unwinds one character at a time"
    print()
    print("original words:", sentence)
    print("reversed words:", reverse_words(sentence))
    print("reversed chars:", reverse_string_recursive(sentence))

    longest = ""
    for word in sentence.split():
        if len(word) > len(longest):
            longest = word
    print("longest word %r reversed is %r" % (longest, reverse_string_recursive(longest)))

    try:
        reverse_string_recursive(12345)
    except TypeError as err:
        print("rejected non-string input:", err)


if __name__ == "__main__":
    main()

