import math


def _validate_numbers(values):
    """Return the input as a list of floats, rejecting non-numeric entries."""
    if isinstance(values, (str, bytes)):
        raise TypeError("expected a list of numbers, got a string")
    cleaned = []
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (index, value))
        if math.isnan(value) or math.isinf(value):
            raise ValueError("element %d is not finite: %r" % (index, value))
        cleaned.append(float(value))
    return cleaned


def calculate_mean(numbers):
    """Arithmetic mean of an already validated list of floats."""
    if not numbers:
        return 0.0
    return math.fsum(numbers) / len(numbers)


def calculate_sample_variance(numbers):
    """Unbiased (n - 1) variance of an already validated list of floats."""
    count = len(numbers)
    if count < 2:
        return 0.0
    mean = calculate_mean(numbers)
    squared = [(value - mean) ** 2 for value in numbers]
    return math.fsum(squared) / (count - 1)


def calculate_sample_std_dev(numbers):
    """Sample standard deviation; 0.0 for lists shorter than two elements."""
    values = _validate_numbers(numbers)
    return math.sqrt(calculate_sample_variance(values))


def summarize(numbers):
    """Build a dictionary describing the spread of a data set."""
    values = _validate_numbers(numbers)
    std_dev = math.sqrt(calculate_sample_variance(values))
    summary = {
        "count": len(values),
        "mean": calculate_mean(values),
        "std_dev": std_dev,
    }
    if std_dev > 0.0:
        mean = summary["mean"]
        summary["z_scores"] = [(value - mean) / std_dev for value in values]
    else:
        summary["z_scores"] = [0.0 for _ in values]
    return summary


def format_summary(numbers):
    """Render a one-line report for a data set."""
    summary = summarize(numbers)
    if summary["count"] == 0:
        return "no data"
    scores = ", ".join("%+.2f" % score for score in summary["z_scores"])
    return "n=%d mean=%.4f sd=%.4f z=[%s]" % (
        summary["count"],
        summary["mean"],
        summary["std_dev"],
        scores,
    )


def main():
    datasets = [[1, 2, 3], [10, 20, 30, 40], [7.5], [], [4, 4, 4, 4]]
    for data in datasets:
        print("%-22r -> %r" % (data, calculate_sample_std_dev(data)))
        print("    " + format_summary(data))


if __name__ == "__main__":
    main()

