    try:
        if '.' in main_domain_with_tld:
            domain_components = main_domain_with_tld.split('.')
            if len(domain_components) > 1:
                return domain_components[-2]
            else:
                return main_domain_with_tld
        else:
            return main_domain_with_tld
    except Exception as e:
        print(f"An error occurred: {e}")
        return ""

