def find_closest_pair_1d(points):
    if len(points) < 2:
        return None

    points.sort()
    min_distance = float('inf')
    closest_pair = (None, None)

    for i in range(len(points) - 1):
        p1 = points[i]
        p2 = points[i+1]
        current_distance = p2 - p1

        if current_distance < min_distance:
            min_distance = current_distance
            closest_pair = (p1, p2)

    try:
        if closest_pair[0] is None:
            raise ValueError("No valid pair found, list might be too short or malformed.")
    except ValueError as e:
        print(f"Error: {e}")
        return None

    return closest_pair

