import sys


def get_quadrant(x, y):
    """Return the quadrant (1-4) of the point (x, y), or 0 if it lies on an axis."""
    for name, value in (("x", x), ("y", y)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("coordinate %s must be an int or a float" % name)
    if x == 0 or y == 0:
        return 0
    if x > 0:
        if y > 0:
            return 1
        return 4
    if y > 0:
        return 2
    return 3


def parse_point(text):
    """Parse a point written as 'x y' or 'x,y' into a pair of floats."""
    cleaned = text.replace(",", " ").strip()
    parts = cleaned.split()
    if len(parts) != 2:
        raise ValueError("expected two coordinates, got %d" % len(parts))
    coordinates = []
    for part in parts:
        try:
            coordinates.append(float(part))
        except ValueError:
