def calculate_median(numbers):
    """Return the median of ``numbers`` without modifying the input list."""
    count = len(numbers)
    if count == 0:
        return None
    ordered = sorted(numbers)
    middle = count // 2
    if count % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2


def parse_numbers(text):
    """Turn a comma or whitespace separated string into a list of numbers."""
    values = []
    for token in text.replace(",", " ").split():
        try:
            number = float(token)
        except ValueError:
            raise ValueError("not a number: {!r}".format(token))
        if number.is_integer():
            number = int(number)
        values.append(number)
    return values


def quartiles(numbers):
    """Return (lower quartile, median, upper quartile) or None values."""
    median = calculate_median(numbers)
    if median is None:
        return (None, None, None)
    ordered = sorted(numbers)
    half = len(ordered) // 2
    lower = ordered[:half]
    if len(ordered) % 2 == 1:
        upper = ordered[half + 1:]
    else:
        upper = ordered[half:]
    return (calculate_median(lower), median, calculate_median(upper))


def format_value(value):
    if value is None:
        return "n/a"
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(numbers):
    """Build a one line report about the spread of ``numbers``."""
    low, median, high = quartiles(numbers)
    parts = ["n={}".format(len(numbers)), "median=" + format_value(median)]
    if low is not None:
        parts.append("Q1=" + format_value(low))
    if high is not None:
        parts.append("Q3=" + format_value(high))
    return ", ".join(parts)


def main():
    samples = ["1, 3, 2", "1 4 2 3", "", "7", "5 1 9 3 8 2", "2.5, 3.5"]
    for sample in samples:
        try:
            numbers = parse_numbers(sample)
        except ValueError as error:
            print("{!r} -> error: {}".format(sample, error))
            continue
        print("{!r} -> {}".format(sample, describe(numbers)))


if __name__ == "__main__":
    main()

