import re

WORD_PATTERN = re.compile(r"[^\W_]+", re.UNICODE)

def extract_words(sentence):
    """Return the lowercase words of the sentence, ignoring punctuation."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    return WORD_PATTERN.findall(sentence.lower())

def find_shortest_word(sentence):
    """Return the first shortest word of the sentence, or '' if there is none."""
    shortest = ""
    for word in extract_words(sentence):
        if not shortest or len(word) < len(shortest):
            shortest = word
    return shortest

def find_longest_word(sentence):
    """Return the first longest word of the sentence, or '' if there is none."""
    longest = ""
    for word in extract_words(sentence):
        if len(word) > len(longest):
            longest = word
    return longest

def length_histogram(sentence):
    """Map each word length to the words of that length, in order of appearance."""
    histogram = {}
    for word in extract_words(sentence):
        histogram.setdefault(len(word), []).append(word)
    return histogram

def format_report(sentence):
    """Build a human readable summary of the words in the sentence."""
    words = extract_words(sentence)
    if not words:
        return "no words found"
    lines = [
        "words: {}".format(len(words)),
        "shortest: {!r}".format(find_shortest_word(sentence)),
        "longest: {!r}".format(find_longest_word(sentence)),
    ]
    histogram = length_histogram(sentence)
    for length in sorted(histogram):
        lines.append("  {:>2} letters: {}".format(length, ", ".join(histogram[length])))
    return "\n".join(lines)

def main():
    sentences = [
        "Hello world, this is a test.",
        "Programming is fun.",
        "   ...!!!   ",
        "Well-known facts: the fox jumps over the lazy dog",
    ]
    for sentence in sentences:
        print("input: {!r}".format(sentence))
        print(format_report(sentence))
        print("-" * 40)

if __name__ == "__main__":
