import calendar
import datetime


def count_business_days(year, month):
    """Return the number of Monday-Friday days in the given month."""
    validate_month(year, month)
    days_in_month = calendar.monthrange(year, month)[1]
    total = 0
    for day in range(1, days_in_month + 1):
        current = datetime.date(year, month, day)
        if current.weekday() < 5:
            total += 1
    return total


def validate_month(year, month):
    """Reject inputs that cannot describe a real calendar month."""
    if not isinstance(year, int) or not isinstance(month, int):
        raise TypeError("year and month must be integers")
    if year < datetime.MINYEAR or year > datetime.MAXYEAR:
        raise ValueError("year %r is outside the supported range" % (year,))
    if month < 1 or month > 12:
        raise ValueError("month %r is not between 1 and 12" % (month,))


def weekday_breakdown(year, month):
    """Map each weekday name to how often it occurs in the month."""
    validate_month(year, month)
    counts = {}
    days_in_month = calendar.monthrange(year, month)[1]
    for day in range(1, days_in_month + 1):
        name = calendar.day_name[datetime.date(year, month, day).weekday()]
        counts[name] = counts.get(name, 0) + 1
    return counts


def count_business_days_in_year(year):
    """Return a list of the business-day counts for every month of a year."""
    counts = []
    for month in range(1, 13):
        counts.append(count_business_days(year, month))
    return counts


def format_year_report(year):
    """Build a printable table of business days per month for one year."""
    lines = []
    monthly = count_business_days_in_year(year)
    for month, business in enumerate(monthly, start=1):
        weekend = calendar.monthrange(year, month)[1] - business
        lines.append(
            "{:<10} {:>3} business days {:>3} weekend days".format(
                calendar.month_name[month], business, weekend
            )
        )
    lines.append("{:<10} {:>3} business days".format("TOTAL", sum(monthly)))
    return "\n".join(lines)


def main():
    for year, month in ((2023, 10), (2023, 11)):
        print("{} {}: {} business days".format(
            calendar.month_name[month], year, count_business_days(year, month)
        ))
    print()
    print(format_year_report(2024))
    print()
    breakdown = weekday_breakdown(2024, 2)
    for index in range(7):
        name = calendar.day_name[index]
        print("{:<10} {}".format(name, breakdown[name]))


if __name__ == "__main__":
    main()

