def filter_dict_by_keys(original_dict, keys_to_keep):
    """Return a new dict with only the pairs whose key appears in keys_to_keep."""
    if not isinstance(original_dict, dict):
        raise TypeError("original_dict must be a dict")
    if isinstance(keys_to_keep, (str, bytes)) or not hasattr(keys_to_keep, "__iter__"):
        raise TypeError("keys_to_keep must be a list of strings")
    wanted = set(keys_to_keep)
    filtered = {}
    for key, value in original_dict.items():
        if key in wanted:
            filtered[key] = value
    return filtered


def missing_keys(original_dict, keys_to_keep):
    """Keys that were requested but are absent from the source dictionary."""
    absent = []
    for key in keys_to_keep:
        if key not in original_dict and key not in absent:
            absent.append(key)
    return absent


def dropped_keys(original_dict, keys_to_keep):
    """Keys of the source dictionary that the filter removes."""
    wanted = set(keys_to_keep)
    return [key for key in original_dict if key not in wanted]


def format_dict(mapping):
    """Render a mapping as a stable, readable one-line string."""
    parts = []
    for key, value in mapping.items():
        if isinstance(value, str):
            parts.append("{}='{}'".format(key, value))
        else:
            parts.append("{}={}".format(key, value))
    return "{" + ", ".join(parts) + "}"


def describe_filtering(original_dict, keys_to_keep):
    """Build a multi-line report about one filtering operation."""
    result = filter_dict_by_keys(original_dict, keys_to_keep)
    lines = [
        "source:   " + format_dict(original_dict),
        "keep:     " + ", ".join(keys_to_keep),
        "result:   " + format_dict(result),
    ]
    removed = dropped_keys(original_dict, keys_to_keep)
    if removed:
        lines.append("dropped:  " + ", ".join(removed))
    absent = missing_keys(original_dict, keys_to_keep)
    if absent:
        lines.append("not found: " + ", ".join(absent))
    return "\n".join(lines)


def main():
    cases = [
        ({'a': 1, 'b': 2, 'c': 3}, ['a', 'c']),
        ({'name': 'Alice', 'age': 30, 'city': 'NY'}, ['name', 'city']),
        ({'name': 'Bob', 'age': 41}, ['name', 'email']),
    ]
    for index, (source, keys) in enumerate(cases, start=1):
        print("case {}".format(index))
        for line in describe_filtering(source, keys).splitlines():
            print("    " + line)
        print()


if __name__ == "__main__":
    main()

