	]
	removed = dropped_keys(original_dict, keys_to_keep)
	if removed:
		lines.append("dropped:  " + ", ".join(removed))
	absent = missing_keys(original_dict, keys_to_keep)
	if absent:
		lines.append("not found: " + ", ".join(absent))
	return "\n".join(lines)


def main():
	cases = [
		({'a': 1, 'b': 2, 'c': 3}, ['a', 'c']),
		({'name': 'Alice', 'age': 30, 'city': 'NY'}, ['name', 'city']),
		({'name': 'Bob', 'age': 41}, ['name', 'email']),
	]
	for index, (source, keys) in enumerate(cases, start=1):
		print("case {}".format(index))
		for line in describe_filtering(source, keys).splitlines():
			print("    " + line)
		print()


if __name__ == "__main__":
	main()

