def find_occurrence_positions(main_string, sub_string):
    """Return the start indexes of every case-insensitive match of sub_string."""
    if not isinstance(main_string, str):
        raise TypeError("main_string must be a str")
    if not isinstance(sub_string, str):
        raise TypeError("sub_string must be a str")
    positions = []
    if not sub_string:
        return positions
    haystack = main_string.lower()
    needle = sub_string.lower()
    index = haystack.find(needle)
    while index != -1:
        positions.append(index)
        index = haystack.find(needle, index + 1)
    return positions


def count_substring_occurrences_ci(main_string, sub_string):
    """Count how often sub_string appears in main_string, ignoring case."""
    return len(find_occurrence_positions(main_string, sub_string))


def describe_positions(positions):
    """Render a list of match indexes as a short human readable string."""
    if not positions:
        return "none"
    return ", ".join(str(position) for position in positions)


def format_report(pairs):
    """Build an aligned text table for (text, pattern) pairs."""
    headers = ("pattern", "count", "positions", "text")
    rows = []
    for main_string, sub_string in pairs:
        positions = find_occurrence_positions(main_string, sub_string)
        rows.append((
            sub_string,
            str(len(positions)),
            describe_positions(positions),
            main_string,
        ))
    widths = []
    for column, title in enumerate(headers):
        widest = len(title)
        for row in rows:
            if len(row[column]) > widest:
                widest = len(row[column])
        widths.append(widest)
    lines = []
    for row in (headers,) + tuple(rows):
        cells = []
        for column, value in enumerate(row):
            cells.append(value.ljust(widths[column]))
        lines.append(" | ".join(cells).rstrip())
    lines.insert(1, "-+-".join("-" * width for width in widths))
    return lines


def main():
    pairs = [
        ("Hello world, World wide web", "world"),
        ("Python is Fun", "fun"),
        ("Mississippi river", "SS"),
        ("aaaa", "aa"),
        ("Nothing to see here", "zebra"),
    ]
    for line in format_report(pairs):
        print(line)
    total = 0
    for main_string, sub_string in pairs:
        total += count_substring_occurrences_ci(main_string, sub_string)
    print("total matches: {}".format(total))


if __name__ == "__main__":
    main()

