VALID_RANGE_MESSAGE = "values must lie between 1 and {}"


def find_missing_element(numbers):
    """Return the single value missing from a permutation of 1..len(numbers)+1."""
    total = len(numbers) + 1
    expected = total * (total + 1) // 2
    actual = 0
    for value in numbers:
        actual += value
    return expected - actual


def validate_sequence(numbers):
    """Raise ValueError unless numbers is a valid permutation with one gap."""
    if not isinstance(numbers, list):
        raise ValueError("input must be a list of integers")
    limit = len(numbers) + 1
    seen = set()
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("input must be a list of integers")
        if value < 1 or value > limit:
            raise ValueError(VALID_RANGE_MESSAGE.format(limit))
        if value in seen:
            raise ValueError("input must contain distinct integers")
        seen.add(value)
    return limit


def parse_sequence(text):
    """Turn a comma or space separated string of digits into a list of ints."""
    cleaned = text.replace(",", " ")
    parsed = []
    for token in cleaned.split():
        try:
            parsed.append(int(token))
        except ValueError:
            raise ValueError("cannot parse {!r} as an integer".format(token))
    return parsed


def describe(numbers):
    """Build a one line report about the sequence and its missing element."""
    limit = validate_sequence(numbers)
    missing = find_missing_element(numbers)
    ordered = sorted(numbers)
    pieces = []
    for value in ordered:
        if value == missing - 1:
            pieces.append("{}>".format(value))
        else:
            pieces.append(str(value))
    return "1..{} as [{}] is missing {}".format(limit, " ".join(pieces), missing)


def main():
    samples = ["1, 2, 4, 5", "5 1 3 2", "2 3 4 5 6 7 1", "1", "9 8 7 6 5 4 3 1"]
    for sample in samples:
        try:
            numbers = parse_sequence(sample)
            line = describe(numbers)
        except ValueError as error:
            line = "rejected {!r}: {}".format(sample, error)
        print(line)

    print(find_missing_element([1, 2, 4, 5]))
    print(find_missing_element([5, 1, 3, 2]))


if __name__ == "__main__":
    main()

