def get_average_movie_rating(movie_ratings):
    average_ratings = {}
    for movie, ratings in movie_ratings.items():
        if ratings:
            total_rating = 0
            for rating in ratings:
                total_rating += rating
            try:
                average = total_rating / len(ratings)
            except ZeroDivisionError:
                average = 0.0
            average_ratings[movie] = average
        else:
            average_ratings[movie] = 0.0
    return average_ratings

