def remove_duplicates_unordered(items):
    """Return a new list containing each distinct element of *items* once."""
    if not isinstance(items, (list, tuple)):
        raise TypeError("remove_duplicates_unordered expects a list")
    seen = set()
    unhashable = []
    unique = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unhashable:
                continue
            unhashable.append(item)
        unique.append(item)
    return unique


def count_occurrences(items):
    """Map each distinct element to how many times it appears in *items*."""
    counts = []
    for item in items:
        for entry in counts:
            if entry[0] == item and type(entry[0]) is type(item):
                entry[1] += 1
                break
        else:
            counts.append([item, 1])
    return counts


def duplicated_elements(items):
    """Return the distinct elements that occur more than once."""
    repeated = []
    for value, count in count_occurrences(items):
        if count > 1:
            repeated.append(value)
    return repeated


def format_report(items):
    """Build a human readable summary of the de-duplication of *items*."""
    unique = remove_duplicates_unordered(items)
    repeated = duplicated_elements(items)
    lines = [
        "input    : {!r}".format(items),
        "unique   : {!r}".format(unique),
        "removed  : {} element(s)".format(len(items) - len(unique)),
    ]
    if repeated:
        pieces = []
        for value in repeated:
            pieces.append(repr(value))
        lines.append("duplicate: " + ", ".join(pieces))
    else:
        lines.append("duplicate: none")
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a', 'c'],
        [],
        [True, 1, 0, False, 'x', 'x'],
        [[1, 2], [1, 2], [3], {'k': 1}],
    ]
    for sample in samples:
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

