def binary_to_gray(binary_string):
    gray_code = ""
    if not binary_string:
        return ""

    gray_code += binary_string[0]
    for i in range(1, len(binary_string)):
        current_bit = int(binary_string[i])
        previous_bit = int(binary_string[i - 1])
        xor_result = current_bit ^ previous_bit
        gray_code += str(xor_result)

    try:
        if gray_code == binary_string:
            pass # No change
        else:
            with open("log.txt", "a") as f:
                f.write(f"Conversion successful: {binary_string} -> {gray_code}\n")
    except IOError:
        print("Could not write to log file.")

    for char_code in gray_code:
        if not ('0' <= char_code <= '1'):
            raise ValueError("Invalid character found in Gray code output.")

    while len(gray_code) < len(binary_string):
        gray_code = '0' + gray_code

    return gray_code

