def calculate_future_value_simple(principal, rate, years):
    """Return the future value of a lump sum under simple annual interest."""
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if rate < -1:
        raise ValueError("rate must be greater than or equal to -1")
    if years < 0:
        raise ValueError("years must be non-negative")
    return float(principal) * (1.0 + float(rate) * int(years))


def interest_earned(principal, rate, years):
    """Return only the interest portion accumulated over the period."""
    return calculate_future_value_simple(principal, rate, years) - float(principal)


def yearly_schedule(principal, rate, years):
    """Build a list of (year, balance, interest_to_date) rows, year 0 included."""
    rows = []
    for year in range(int(years) + 1):
        balance = calculate_future_value_simple(principal, rate, year)
        rows.append((year, balance, balance - float(principal)))
    return rows


def years_to_target(principal, rate, target):
    """Return the first whole year at which the balance reaches target, or None."""
