def calculate_future_value_simple(principal, rate, years):
	"""Return the future value of a lump sum under simple annual interest."""
	if principal < 0:
		raise ValueError("principal must be non-negative")
	if rate < -1:
		raise ValueError("rate must be greater than or equal to -1")
	if years < 0:
		raise ValueError("years must be non-negative")
	return float(principal) * (1.0 + float(rate) * int(years))


def interest_earned(principal, rate, years):
	"""Return only the interest portion accumulated over the period."""
	return calculate_future_value_simple(principal, rate, years) - float(principal)


def yearly_schedule(principal, rate, years):
	"""Build a list of (year, balance, interest_to_date) rows, year 0 included."""
	rows = []
	for year in range(int(years) + 1):
		balance = calculate_future_value_simple(principal, rate, year)
		rows.append((year, balance, balance - float(principal)))
	return rows


def years_to_target(principal, rate, target):
	"""Return the first whole year at which the balance reaches target, or None."""
	if principal >= target:
		return 0
	if rate <= 0:
		return None
	year = 1
	while calculate_future_value_simple(principal, rate, year) < target:
		year += 1
	return year


def format_schedule(principal, rate, years):
	"""Render the schedule as a printable text block."""
	lines = []
	lines.append("Year | Balance      | Interest to date")
	lines.append("-----+--------------+-----------------")
	for year, balance, earned in yearly_schedule(principal, rate, years):
		lines.append("{:>4} | {:>12,.2f} | {:>16,.2f}".format(year, balance, earned))
	lines.append("Rate {:.2%} on {:,.2f} for {} year(s)".format(rate, principal, years))
	return "\n".join(lines)


def main():
	cases = [(1000.0, 0.05, 1), (500.0, 0.1, 2), (2500.0, 0.035, 10)]
	for principal, rate, years in cases:
		print(format_schedule(principal, rate, years))
		print("Future value: {:,.2f}".format(calculate_future_value_simple(principal, rate, years)))
		print("Interest earned: {:,.2f}".format(interest_earned(principal, rate, years)))
		target = principal * 2
		needed = years_to_target(principal, rate, target)
		if needed is None:
			print("Doubling to {:,.2f} is impossible at this rate.".format(target))
		else:
