def days_in_month(year, month):
    """Return the number of days in the given month of the given year."""
    if month == 2:
        if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
            return 29
        return 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def parse_date(date_str):
    """Validate a 'YYYY-MM-DD' string and return it as an (year, month, day) tuple."""
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % (date_str,))
    if [len(part) for part in parts] != [4, 2, 2]:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % (date_str,))
    for part in parts:
        if not part.isdigit():
            raise ValueError("date must contain digits only: %r" % (date_str,))
    year, month, day = (int(part) for part in parts)
    if month < 1 or month > 12:
        raise ValueError('month out of range: %d' % month)
    if day < 1 or day > days_in_month(year, month):
        raise ValueError('day out of range: %d' % day)
    return year, month, day


def add_calendar_event(calendar, date_str, event_description):
    """Append event_description to the list of events stored under date_str."""
    parse_date(date_str)
    description = event_description.strip()
    if not description:
        raise ValueError('event description must not be empty')
    if date_str not in calendar:
        calendar[date_str] = []
    calendar[date_str].append(description)


def format_calendar(calendar):
    """Build a human readable listing of every scheduled event, oldest date first."""
    lines = []
    for date_str in sorted(calendar):
        events = calendar[date_str]
        if not events:
