        lines.append('%s (%d event%s)' % (date_str, len(events), '' if len(events) == 1 else 's'))
        for number, description in enumerate(events, start=1):
            lines.append('    %d. %s' % (number, description))
    if not lines:
        return 'No events scheduled.'
    return '\n'.join(lines)


