def character_frequency(text):
    """Count occurrences of each character in text, ignoring case and whitespace."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    counts = {}
    for character in text:
        if character.isspace():
            continue
        key = character.lower()
        if key in counts:
            counts[key] += 1
        else:
            counts[key] = 1
    return counts


def most_common(counts, limit=3):
    """Return up to `limit` (character, count) pairs, highest count first."""
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def repeated_characters(counts):
    """Return the characters that occur more than once, in alphabetical order."""
    repeated = []
    for character in sorted(counts):
        if counts[character] > 1:
            repeated.append(character)
    return repeated


def format_report(text, counts):
    """Build a human readable multi-line summary of a frequency dictionary."""
    total = sum(counts.values())
    lines = ["Text: %r" % text]
    lines.append("Distinct characters: %d" % len(counts))
    lines.append("Counted characters: %d" % total)
    for character, count in most_common(counts):
        share = 100.0 * count / total if total else 0.0
        lines.append("  %r appears %d time(s) (%.1f%%)" % (character, count, share))
    repeated = repeated_characters(counts)
    if repeated:
        lines.append("Repeated: " + ", ".join(repeated))
    else:
        lines.append("Repeated: none")
    return "\n".join(lines)


def merge_frequencies(texts):
    """Combine the character frequencies of several strings into one dictionary."""
    combined = {}
    for text in texts:
        for character, count in character_frequency(text).items():
            combined[character] = combined.get(character, 0) + count
    return combined


def main():
    samples = ["Hello World", "Python", "Mississippi river"]
    for sample in samples:
        counts = character_frequency(sample)
        print(format_report(sample, counts))
        print()
    combined = merge_frequencies(samples)
    print("Combined totals over %d samples:" % len(samples))
    for character in sorted(combined):
        bar = "#" * combined[character]
        print("  %s %2d %s" % (character, combined[character], bar))
    vowels = 0
    for character, count in combined.items():
        if character in "aeiou":
            vowels += count
    print("Vowel characters in total: %d" % vowels)


if __name__ == "__main__":
    main()

