    text = argument.strip()
    if not text.isdigit():
        raise ValueError("expected a non-negative whole number, got %r" % argument)
    return int(text)


def format_sequence(sequence, per_row=8):
    """Render a sequence as right-aligned columns of at most per_row entries."""
    if not sequence:
        return "(empty sequence)"
    width = max(len(str(value)) for value in sequence)
    lines = []
    for start in range(0, len(sequence), per_row):
        row = sequence[start:start + per_row]
        lines.append(" ".join(str(value).rjust(width) for value in row))
    return "\n".join(lines)


def summarize(sequence):
