            raise TypeError("all elements must be integers, got %r" % (value,))
        if value < 1 or value > n:
            raise ValueError("element %d is outside the range 1..%d" % (value, n))
        if value in seen:
            raise ValueError("element %d appears more than once" % value)
        seen.add(value)
    return n


