def proper_divisors(num):
    """Return the sorted proper positive divisors of a positive integer."""
    if not isinstance(num, int) or isinstance(num, bool):
        raise TypeError("num must be an integer")
    if num < 1:
        raise ValueError("num must be a positive integer")
    divisors = [1] if num > 1 else []
    step = 2
    while step * step <= num:
        if num % step == 0:
            divisors.append(step)
            partner = num // step
            if partner != step:
                divisors.append(partner)
        step += 1
    divisors.sort()
    return divisors


def is_perfect_number(num):
    """Return True when num equals the sum of its proper positive divisors."""
    if num < 2:
        return False
    return sum(proper_divisors(num)) == num


def classify(num):
    """Label num as 'perfect', 'abundant' or 'deficient'."""
    total = sum(proper_divisors(num))
    if total == num:
        return "perfect"
    if total > num:
        return "abundant"
    return "deficient"


def describe(num):
    """Build a human readable line explaining the classification of num."""
    divisors = proper_divisors(num)
    if divisors:
        parts = " + ".join(str(d) for d in divisors)
    else:
        parts = "(none)"
    return "{0:>5} = {1} -> {2} ({3})".format(num, parts, sum(divisors), classify(num))


def perfect_numbers_up_to(limit):
    """Collect every perfect number in the inclusive range 1..limit."""
    found = []
    for candidate in range(1, limit + 1):
        if is_perfect_number(candidate):
            found.append(candidate)
    return found


def main():
    limit = 500
    perfects = perfect_numbers_up_to(limit)
    print("Perfect numbers up to {0}: {1}".format(limit, perfects))
    for number in perfects:
