VOWELS = frozenset("aeiou")


def count_vowels_consonants(text):
    vowel_count = 0
    consonant_count = 0
    for char in text:
        if not char.isalpha():
            continue
        if char.lower() in VOWELS:
            vowel_count += 1
        else:
            consonant_count += 1
    return vowel_count, consonant_count


def letter_ratio(vowel_count, consonant_count):
    total = vowel_count + consonant_count
    if total == 0:
        return 0.0
    return vowel_count / total


def describe(text):
    vowels, consonants = count_vowels_consonants(text)
    ratio = letter_ratio(vowels, consonants)
    if vowels + consonants == 0:
        verdict = "no letters"
    elif ratio > 0.5:
        verdict = "vowel-heavy"
    elif ratio < 0.3:
        verdict = "consonant-heavy"
    else:
        verdict = "balanced"
    return {
        "text": text,
        "vowels": vowels,
        "consonants": consonants,
        "ratio": ratio,
        "verdict": verdict,
    }


def format_report(reports):
    width = 0
    for report in reports:
        if len(report["text"]) > width:
            width = len(report["text"])
    lines = []
    for report in reports:
        lines.append(
            "{text:<{width}}  vowels={vowels:>3}  consonants={consonants:>3}"
            "  ratio={ratio:>5.2f}  {verdict}".format(width=width, **report)
        )
    return "\n".join(lines)


