from collections import deque


class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right


def build_tree(values):
    """Build a binary tree from a level-order list where None means 'no node'."""
    if not values or values[0] is None:
        return None
    root = Node(values[0])
    pending = deque([root])
    index = 1
    while pending and index < len(values):
        current = pending.popleft()
        if index < len(values):
            value = values[index]
            index += 1
            if value is not None:
                current.left = Node(value)
                pending.append(current.left)
        if index < len(values):
            value = values[index]
            index += 1
            if value is not None:
                current.right = Node(value)
                pending.append(current.right)
    return root


def is_symmetric(root):
    """Return True if the tree rooted at `root` is a mirror image of itself."""
    if root is None:
        return True
    pairs = deque([(root.left, root.right)])
    while pairs:
        left, right = pairs.popleft()
        if left is None and right is None:
            continue
        if left is None or right is None:
            return False
        if left.value != right.value:
            return False
        pairs.append((left.left, right.right))
        pairs.append((left.right, right.left))
    return True


def to_level_order(root):
    """Serialize a tree back to a level-order list, trimming trailing gaps."""
    result = []
    pending = deque([root])
    while pending:
        current = pending.popleft()
        if current is None:
            result.append(None)
        else:
            result.append(current.value)
            pending.append(current.left)
            pending.append(current.right)
    while result and result[-1] is None:
        result.pop()
    return result


def describe(values):
    root = build_tree(values)
    label = ",".join("null" if v is None else str(v) for v in to_level_order(root))
    return "{0:<24} -> {1}".format(label or "(empty)", is_symmetric(root))


def main():
    cases = [
        [1, 2, 2, 3, 4, 4, 3],
        [1, 2, 2, None, 3, None, 3],
        [],
        [7],
        [1, 2, 2, None, None, None, None],
    ]
    for case in cases:
        print(describe(case))


if __name__ == "__main__":
    main()

