import re
import sys

TOKEN_PATTERN = re.compile(r"[a-z0-9]+(?:'[a-z]+)*")


def normalize(text):
    """Lowercase the text and strip characters that cannot belong to a word."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got %s" % type(text).__name__)
    lowered = text.lower()
    cleaned = []
    for char in lowered:
        if char.isalnum() or char == "'":
            cleaned.append(char)
        else:
            cleaned.append(' ')
    return ''.join(cleaned)


def tokenize(text):
    """Split normalized text into bare words, dropping stray apostrophes."""
    words = []
    for match in TOKEN_PATTERN.finditer(normalize(text)):
        word = match.group(0).strip("'")
        if word:
            words.append(word)
    return words


def word_counts(text):
    """Count occurrences of each word in text, ignoring case and punctuation."""
    counts = {}
    for word in tokenize(text):
        counts[word] = counts.get(word, 0) + 1
    return counts


def most_common(counts, limit=None):
    """Return (word, count) pairs sorted by descending count, then alphabetically."""
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    if limit is None:
        return ordered
    if limit < 0:
        raise ValueError("limit must not be negative")
    return ordered[:limit]


def format_report(counts, limit=None):
    """Build an aligned table of word frequencies for printing."""
    rows = most_common(counts, limit)
    if not rows:
        return 'no words found'
    width = max(len(word) for word, _ in rows)
    total = sum(counts.values())
    lines = []
    for word, count in rows:
        share = 100.0 * count / total
        lines.append('%-*s %4d  %5.1f%%' % (width, word, count, share))
    lines.append('%-*s %4d' % (width, 'TOTAL', total))
    return '\n'.join(lines)


def main(argv):
    if len(argv) > 1:
        text = ' '.join(argv[1:])
    else:
        text = sys.stdin.read()
    counts = word_counts(text)
    print(format_report(counts, limit=20))
    unique = len(counts)
    if unique == 0:
        return 1
    print('%d distinct word(s)' % unique)
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

