import random


def validate_input(nums, k):
    if not isinstance(nums, (list, tuple)):
        raise TypeError("nums must be a list or tuple")
    for value in nums:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("nums must contain only numbers")
    if not isinstance(k, int) or isinstance(k, bool):
        raise TypeError("k must be an integer")
    if k < 1 or k > len(nums):
        raise ValueError("k must satisfy 1 <= k <= len(nums)")


def partition(items, left, right, pivot_index):
    pivot = items[pivot_index]
    items[pivot_index], items[right] = items[right], items[pivot_index]
    store = left
    for i in range(left, right):
        if items[i] > pivot:
            items[i], items[store] = items[store], items[i]
            store += 1
    items[store], items[right] = items[right], items[store]
    return store


def quickselect(items, target_index):
    left, right = 0, len(items) - 1
    while left < right:
        pivot_index = random.randint(left, right)
        pivot_index = partition(items, left, right, pivot_index)
        if pivot_index == target_index:
            return items[pivot_index]
        elif pivot_index < target_index:
            left = pivot_index + 1
        else:
            right = pivot_index - 1
    return items[left]


def find_kth_largest(nums, k):
    validate_input(nums, k)
    return quickselect(list(nums), k - 1)


