def validate(nums):
    """Check that nums is a non-empty sequence of numbers and return it as a list."""
    if not isinstance(nums, (list, tuple)):
        raise TypeError("nums must be a list or tuple")
    values = list(nums)
    if not values:
        raise ValueError("nums must contain at least one element")
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element at index %d is not a number" % index)
    return values


def find_all_peaks(values):
    """Return every index whose value is greater than both of its neighbours."""
    peaks = []
    last = len(values) - 1
    for index, value in enumerate(values):
        left_ok = index == 0 or values[index - 1] < value
        right_ok = index == last or values[index + 1] < value
        if left_ok and right_ok:
            peaks.append(index)
    return peaks


def find_peak_element(nums):
    """Return the index of an element strictly greater than its neighbours."""
    values = validate(nums)
    flat = any(values[i] == values[i + 1] for i in range(len(values) - 1))
    if flat:
        peaks = find_all_peaks(values)
        if not peaks:
            raise ValueError("nums contains no strict peak element")
        return peaks[0]
    low, high = 0, len(values) - 1
    while low < high:
        mid = (low + high) // 2
        if values[mid] < values[mid + 1]:
            low = mid + 1
        else:
            high = mid
    return low


def describe(nums):
    """Build a human readable report about the peaks of nums."""
    values = validate(nums)
    peak = find_peak_element(values)
    lines = ["input: %s" % (values,)]
    lines.append("selected peak: index %d, value %s" % (peak, values[peak]))
    labels = []
    for index in find_all_peaks(values):
        labels.append("%d->%s" % (index, values[index]))
    lines.append("all peaks: " + ", ".join(labels))
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 3, 1],
        [1, 2, 1, 3, 5, 6, 4],
        [1],
        [5, 4, 3, 2, 1],
        [1, 2, 3, 4, 5],
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)
    rejected = [[], "abc", [1, None, 3], [2, 2, 2]]
    for item in rejected:
        try:
            find_peak_element(item)
        except (TypeError, ValueError) as error:
            print("rejected %r: %s" % (item, error))


if __name__ == "__main__":
    main()

