import random


def simulate_dice_rolls(n):
    """Roll a fair six-sided die n times and return the list of outcomes."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    rolls = []
    for _ in range(n):
        rolls.append(random.randint(1, 6))
    return rolls


def tally_rolls(rolls):
    """Count how often each face 1..6 appears in rolls."""
    counts = {face: 0 for face in range(1, 7)}
    for roll in rolls:
        if roll not in counts:
            raise ValueError("invalid die face: {0!r}".format(roll))
        counts[roll] += 1
    return counts


def average_roll(rolls):
    """Mean value of the rolls, or 0.0 when there are none."""
    if not rolls:
        return 0.0
    return sum(rolls) / len(rolls)


def format_histogram(counts, width=40):
    """Render the tally as text bars scaled to at most `width` characters."""
    busiest = max(counts.values())
    lines = []
    for face in sorted(counts):
        count = counts[face]
        if busiest > 0:
            bar_length = int(round(width * count / busiest))
        else:
            bar_length = 0
        lines.append("{0}: {1:<{2}} {3}".format(face, "#" * bar_length, width, count))
    return "\n".join(lines)


def longest_run(rolls):
    """Length of the longest streak of identical consecutive rolls."""
    best = 0
    current = 0
    previous = None
    for roll in rolls:
        if roll == previous:
            current += 1
        else:
            current = 1
            previous = roll
        if current > best:
            best = current
    return best


def main():
    trial_sizes = [10, 600]
    for size in trial_sizes:
        rolls = simulate_dice_rolls(size)
        counts = tally_rolls(rolls)
        print("=== {0} rolls ===".format(size))
        if size <= 20:
            print("outcomes:", rolls)
        print(format_histogram(counts))
        print("average: {0:.3f}".format(average_roll(rolls)))
        print("longest streak: {0}".format(longest_run(rolls)))
        print()


if __name__ == "__main__":
    main()

