def is_symmetric_matrix(matrix):
    n = len(matrix)
    if n == 0:
        return True
    for row in matrix:
        if len(row) != n:
            return False

    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

