def word_wrap(text, max_width):
    words = text.split()
    wrapped_lines = []
    current_line = []

    for word in words:
        if not current_line:
            current_line.append(word)
        else:
            if len(' '.join(current_line) + ' ' + word) <= max_width:
                current_line.append(word)
            else:
                wrapped_lines.append(' '.join(current_line))
                current_line = [word]

    if current_line:
        wrapped_lines.append(' '.join(current_line))

    final_output = []
    for line in wrapped_lines:
