def count_occurrences(items):
    """Return a mapping from element to the number of times it appears."""
    counts = {}
    for item in items:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1
    return counts


def find_duplicates(items):
    """Return a list of the elements that appear more than once in items."""
    counts = count_occurrences(items)
    duplicates = []
    for item, total in counts.items():
        if total > 1:
            duplicates.append(item)
    return duplicates


def duplicate_report(items):
    """Return lines describing each duplicated element and its repeat count."""
    counts = count_occurrences(items)
    lines = []
    for item in find_duplicates(items):
        extra = counts[item] - 1
        if extra == 1:
            lines.append("{!r} appears twice".format(item))
        else:
            lines.append("{!r} appears {} times".format(item, counts[item]))
    return lines


