def power_iterative(base, exponent):
    """Return base raised to exponent using iterative exponentiation by squaring."""
    if not isinstance(exponent, int) or isinstance(exponent, bool):
        raise TypeError("exponent must be an integer")
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    result = 1
    factor = base
    remaining = exponent
    while remaining > 0:
        if remaining % 2 == 1:
            result *= factor
        remaining //= 2
        if remaining > 0:
            factor *= factor
    return result


def power_table(bases, exponents):
    """Build a mapping from (base, exponent) pairs to their computed powers."""
    table = {}
    for base in bases:
        for exponent in exponents:
            table[(base, exponent)] = power_iterative(base, exponent)
    return table


def format_row(base, exponents, table):
    """Render one line of the power table for a single base."""
    cells = []
    for exponent in exponents:
        cells.append("{:>8}".format(table[(base, exponent)]))
    return "{:>4} |".format(base) + "".join(cells)


def render_table(bases, exponents):
    """Return the full power table as a list of printable lines."""
    table = power_table(bases, exponents)
    header = "base |" + "".join("{:>8}".format("^" + str(e)) for e in exponents)
    lines = [header, "-" * len(header)]
    for base in bases:
        lines.append(format_row(base, exponents, table))
    return lines


def parse_pair(text):
    """Parse a 'base exponent' string into a tuple of two integers."""
    parts = text.split()
    if len(parts) != 2:
        raise ValueError("expected exactly two values, got {!r}".format(text))
    values = []
    for part in parts:
        try:
            values.append(int(part))
        except ValueError:
            raise ValueError("not an integer: {!r}".format(part))
    return values[0], values[1]


def report(requests):
    """Evaluate textual power requests, returning one report line per request."""
    lines = []
    for text in requests:
        try:
            base, exponent = parse_pair(text)
            value = power_iterative(base, exponent)
        except ValueError as err:
            lines.append("{} -> error: {}".format(text, err))
        else:
            lines.append("{} ** {} = {}".format(base, exponent, value))
    return lines


def main():
    for line in render_table([2, 3, 5, 10], [0, 1, 2, 3, 5]):
        print(line)
    print()
    for line in report(["2 3", "5 0", "7 11", "4 -1", "x 2"]):
        print(line)


if __name__ == "__main__":
    main()

