def reverse_segment(nums, start, end):
    """Reverse nums[start:end+1] in place."""
    while start < end:
        nums[start], nums[end] = nums[end], nums[start]
        start += 1
        end -= 1


def next_permutation(nums):
    """Rearrange nums into the next lexicographically greater permutation.

    If nums is already the highest permutation, it becomes the lowest one.
    The list is modified in place.
    """
    pivot = len(nums) - 2
    while pivot >= 0 and nums[pivot] >= nums[pivot + 1]:
        pivot -= 1
    if pivot >= 0:
        successor = len(nums) - 1
        while nums[successor] <= nums[pivot]:
            successor -= 1
        nums[pivot], nums[successor] = nums[successor], nums[pivot]
    reverse_segment(nums, pivot + 1, len(nums) - 1)
    return nums


def permutation_cycle(nums):
    """Yield every permutation of nums, starting from the sorted order."""
    current = sorted(nums)
    first = tuple(current)
    while True:
        yield tuple(current)
        next_permutation(current)
        if tuple(current) == first:
            return


def validate(nums):
    """Reject inputs that are not lists of mutually comparable numbers."""
    if not isinstance(nums, list):
