def find_largest(numbers: list[int | float]) -> int | float:
    """Return the largest element of a non-empty list of numbers."""
    largest = numbers[0]
    for value in numbers[1:]:
        if value > largest:
            largest = value
    return largest


def parse_numbers(text: str) -> list[int | float]:
    """Turn a comma- or space-separated string into a list of numbers."""
    tokens = text.replace(",", " ").split()
    numbers: list[int | float] = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            numbers.append(float(token))
    return numbers


def index_of_largest(numbers: list[int | float]) -> int:
    """Return the position of the first occurrence of the largest element."""
    largest = find_largest(numbers)
    for position, value in enumerate(numbers):
        if value == largest:
            return position
    raise AssertionError("largest element must be present in the list")


def format_number(value: int | float) -> str:
    """Render a number without a trailing '.0' for whole floats."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(numbers: list[int | float]) -> str:
    """Build a one-line report about the largest element of a list."""
    if not numbers:
        return "empty list: no largest element"
    largest = find_largest(numbers)
    position = index_of_largest(numbers)
    shown = ", ".join(format_number(value) for value in numbers)
    return (
        f"[{shown}] -> largest {format_number(largest)} "
        f"at index {position} of {len(numbers)}"
    )


def main() -> None:
    datasets = [
        "3, 1, 4, 1, 5, 9, 2",
        "-5 -1 -10",
        "2.5, 7.0, 7, 1.25",
    ]
    for raw in datasets:
        numbers = parse_numbers(raw)
        print(describe(numbers))

    combined: list[int | float] = []
    for raw in datasets:
        combined.extend(parse_numbers(raw))
    print("overall maximum:", format_number(find_largest(combined)))


if __name__ == "__main__":
    main()

