import sys


def sum_digits(n: int) -> int:
    """Return the sum of the decimal digits of a non-negative integer."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("sum_digits() requires an int")
    if n < 0:
        raise ValueError("sum_digits() requires a non-negative int")
    total = 0
    while n > 0:
        total += n % 10
        n //= 10
    return total


def digital_root(n: int) -> int:
    """Repeatedly sum the digits until a single digit remains."""
    value = sum_digits(n)
    while value > 9:
        value = sum_digits(value)
    return value


def digit_counts(n: int) -> dict:
    """Map each digit present in n to how often it occurs."""
    counts = {}
    for character in str(n):
        digit = int(character)
        counts[digit] = counts.get(digit, 0) + 1
    return counts


def parse_number(text: str) -> int:
    """Convert a command line argument into a non-negative integer."""
    cleaned = text.replace("_", "").replace(",", "").strip()
    if not cleaned.isdigit():
        raise ValueError("not a non-negative integer: %r" % text)
    return int(cleaned)


def format_report(n: int) -> str:
    """Build a one-line description of the digit statistics of n."""
    counts = digit_counts(n)
    pieces = []
    for digit in sorted(counts):
        count = counts[digit]
        if count == 1:
            pieces.append(str(digit))
        else:
            pieces.append("%d x%d" % (digit, count))
    return "%d -> sum %d, root %d, digits: %s" % (
        n,
        sum_digits(n),
        digital_root(n),
        ", ".join(pieces),
    )


def main(argv: list) -> int:
    if len(argv) < 2:
        print("usage: %s NUMBER [NUMBER ...]" % argv[0], file=sys.stderr)
        return 2
    status = 0
    for argument in argv[1:]:
        try:
            number = parse_number(argument)
        except ValueError as error:
            print("error: %s" % error, file=sys.stderr)
            status = 1
            continue
        print(format_report(number))
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv))

