def remove_char_at_index(text: str, index: int) -> str:
    """Return `text` with the character at position `index` removed."""
    return text[:index] + text[index + 1:]


def normalize_index(text: str, index: int) -> int:
    """Translate a possibly negative index into a plain forward position."""
    if index < 0:
        return len(text) + index
    return index


def is_valid_index(text: str, index: int) -> bool:
    """Report whether `index` addresses an existing character of `text`."""
    position = normalize_index(text, index)
    return 0 <= position < len(text)


def remove_all_occurrences(text: str, char: str) -> str:
    """Remove every occurrence of `char` by repeatedly deleting one index."""
    result = text
    position = result.find(char)
    while position != -1:
        result = remove_char_at_index(result, position)
        position = result.find(char)
    return result


def remove_indices(text: str, indices) -> str:
    """Remove several characters at once, ignoring positions out of range."""
    targets = set()
    for index in indices:
        if is_valid_index(text, index):
            targets.add(normalize_index(text, index))
    kept = []
    for position, char in enumerate(text):
        if position not in targets:
            kept.append(char)
    return "".join(kept)


