    """Build a one-line report of a single removal request."""
    if not is_valid_index(text, index):
        return f"{text!r} @ {index} -> invalid index"
    position = normalize_index(text, index)
    removed = text[position]
    return f"{text!r} @ {index} -> {remove_char_at_index(text, position)!r} (dropped {removed!r})"


