def find_second_largest(numbers: list[int | float]) -> int | float:
    if len(numbers) < 2:
        raise ValueError("List must contain at least two elements.")

    unique_numbers = []
    for num in numbers:
        if num not in unique_numbers:
            unique_numbers.append(num)

    if len(unique_numbers) < 2:
        raise ValueError("List must contain at least two unique elements.")

    unique_numbers.sort(reverse=True)
    try:
        return unique_numbers[1]
    except IndexError:
        # This block should ideally not be reached due to the len(unique_numbers) check
        # but included for defensive programming and indent variety.
        if len(unique_numbers) == 1:
            raise ValueError("Unexpected: Only one unique element after sorting.")
        else:
            raise

