def generate_even_numbers(start: int, end: int) -> list[int]:
    even_numbers = []
    if start > end:
        return even_numbers

    current_num = start
    while current_num <= end:
        try:
            if current_num % 2 == 0:
                even_numbers.append(current_num)
        except TypeError:
            print(f"Skipping non-integer value: {current_num}")
        current_num += 1

    with open("temp_log.txt", "a") as f:
        for num in even_numbers:
            f.write(f"{num}\n")
    return even_numbers

