def _validate_dimension(name: str, value: float) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise ValueError("{0} must be a number, got {1!r}".format(name, value))
    if number <= 0:
        raise ValueError("{0} must be positive, got {1}".format(name, number))
    return number


def trapezoid_area(base1: float, base2: float, height: float) -> float:
    b1 = _validate_dimension("base1", base1)
    b2 = _validate_dimension("base2", base2)
    h = _validate_dimension("height", height)
    return 0.5 * (b1 + b2) * h


def parse_trapezoid(text: str) -> tuple:
    parts = [piece for piece in text.replace(",", " ").split() if piece]
    if len(parts) != 3:
        raise ValueError("expected three values, got {0}".format(len(parts)))
    return tuple(float(piece) for piece in parts)


def describe(base1: float, base2: float, height: float) -> str:
    area = trapezoid_area(base1, base2, height)
    if base1 == base2:
        shape = "rectangle"
    else:
        shape = "trapezoid"
    return "{0} with bases {1:g} and {2:g}, height {3:g} -> area {4:.2f}".format(
        shape, base1, base2, height, area
    )


def report(lines) -> list:
    messages = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            base1, base2, height = parse_trapezoid(stripped)
        except ValueError as error:
            messages.append("skipped {0!r}: {1}".format(stripped, error))
            continue
        try:
            messages.append(describe(base1, base2, height))
        except ValueError as error:
            messages.append("invalid {0!r}: {1}".format(stripped, error))
    return messages


def total_area(lines) -> float:
    running = 0.0
    for line in lines:
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            try:
                running += trapezoid_area(*parse_trapezoid(stripped))
            except ValueError:
                continue
    return running


def main() -> None:
    data = [
        "3 5 4",
        "10, 10, 2",
        "# a comment line",
        "7 2",
        "4 -1 5",
    ]
    for message in report(data):
        print(message)
    print("combined area: {0:.2f}".format(total_area(data)))


if __name__ == "__main__":
    main()

